import{_ as i,l,o as e,c as o,v as t,p as n,x as s,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"高层次综合 HLS","description":"","frontmatter":{"title":"高层次综合 HLS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hls.md","filePath":"cs/hls.md","lastUpdated":1789023840000}'),c={name:"cs/hls.md"};function E(L,a,S,A,T,C){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="高层次综合-hls" tabindex="-1">高层次综合 HLS <a class="header-anchor" href="#高层次综合-hls" aria-label="Permalink to &quot;高层次综合 HLS&quot;">​</a></h1><div class="epigraph"><p>从 C/C++ 的循环生成流水线 RTL：调度决定哪一拍做乘，绑定决定用几份 DSP；程序员写的仍是算法，工具补时序状态机。</p><footer>—— 据 Coussy and Morawiec, High-Level Synthesis；Gajski et al., High-Level Synthesis 整理</footer></div><p><a href="/cs/fpga-place-route">上一课</a>把手工 RTL 送到 P&amp;R。算术单元里的<a href="/cs/wallace-carry-save">华莱士</a>与<a href="/cs/fixed-point-dsp">定点 MAC</a> 用 C 写往往更短。缺口是 <strong>HLS</strong>：把高级语言调度成 RTL，再走同一套综合与布局，而不是在 FPGA 上跑 CPU 解释 C。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTL 要显写流水线级与握手。<a href="/cs/verilog-basics">Verilog 基本</a>已警告不要把 HDL 当软件。HLS 反向：接受「软件式」循环，用约束（目标周期、II、数组到 RAM/LUT 的绑定）推出状态机与数据通路。缺口不是新的乘法器电路，而是<strong>调度与绑定</strong>这两步。</p><p>II（initiation interval）=1 意味着每拍启动下一次循环迭代，需要足够的 DSP 与内存端口。这与组成课流水线是同一思想，工具自动插寄存器。</p><h3 id="hls-不是「保证比手写-rtl-更快」" tabindex="-1">HLS 不是「保证比手写 RTL 更快」 <a class="header-anchor" href="#hls-不是「保证比手写-rtl-更快」" aria-label="Permalink to &quot;HLS 不是「保证比手写 RTL 更快」&quot;">​</a></h3><p>质量取决于可综合子集、依赖分析、是否把数组分区。随意指针与系统调用无法变电路。把 HLS 当成在 PL 里跑 Linux 用户程序，会与软核 CPU 方案混层。</p><p><span class="marginnote">Gajski 等人定义 HLS 的调度/绑定/分配。现代工具（Vitis HLS 等）实现不同，本课钉共同步骤。本栏不把 HLS 写成大模型算子生成器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：C 函数 + 接口 pragma（AXI 流、寄存器）。分析循环携带依赖。调度：在周期约束下安排运算。绑定：运算映射到 FPGA DSP 或 ASIC 乘法器。输出：RTL，然后<a href="/cs/synthesis-netlist">综合</a>与 P&amp;R。验证：C 仿真 vs RTL 协同仿真——后课测试平台家族。</p>',11)),(e(),n(p,null,{default:s(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22C%20%E5%BE%AA%E7%8E%AF%20%2B%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E4%B8%8E%E7%BB%91%E5%AE%9A%22%5D%0A%20%20SCH%20--%3E%20RTL%5B%22%E7%94%9F%E6%88%90%20RTL%22%5D%0A%20%20RTL%20--%3E%20PNR%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E7%BB%BC%E5%90%88%E4%B8%8E%20P%26R%22%5D%0A%20%20PNR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AASIC%20%E6%A0%87%E5%87%86%E5%8D%95%E5%85%83%E5%8F%A6%E4%B8%80%E6%9D%A1%E8%B7%AF%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>定点类型在 HLS 里常显式标注位宽，对应定点 DSP 课的 Q 格式，而不是偷偷用 <code>float</code> 然后抱怨资源。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 ASIC 流程也可以 HLS 到标准单元，只是库不同。手写 RTL 仍适合控制密集与极限时序（异步 FIFO 指针）。HLS 适合规则循环的算术阵列。验证负担不消失：生成 RTL 仍要 STA 与功能测试。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教某 pragma 清单，不把 PyTorch 图到 FPGA 的工具链写进主干（那会滑向大模型栏）。不声称 HLS 取代 CDC 设计：跨时钟仍要 FIFO 或工具认的同步器原语。</p><p>后课默认：HLS 产出仍是 RTL，走同一时序闭合；调度/绑定是新增的自动层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>C 循环经调度与绑定变成流水线 RTL。</li><li>仍要综合、STA、P&amp;R；不是在 LUT 上解释 C。</li><li>不规则控制与 CDC 仍宜手写。</li><li>出处：Coussy and Morawiec；Gajski et al., <em>High-Level Synthesis</em>。</li></ul>',8))])}const P=i(c,[["render",E]]);export{_ as __pageData,P as default};
